<?php
namespace Tests\Feature;
use App\Actions\Rental\CreateRentalBooking;use App\Actions\Rental\TransitionRentalBooking;use App\Models\CatalogEntity;use App\Models\CatalogOffer;use App\Models\MediaAsset;use App\Models\Mitra;use App\Models\RentalRate;use App\Models\RenterDocument;use App\Models\ServiceType;use App\Models\User;use Database\Seeders\FoundationReferenceSeeder;use Illuminate\Foundation\Testing\RefreshDatabase;use Illuminate\Validation\ValidationException;use Tests\TestCase;
class RentalModuleTest extends TestCase
{use RefreshDatabase;protected function setUp():void{parent::setUp();$this->seed(FoundationReferenceSeeder::class);}public function test_booking_rejects_overlap_and_blocked_dates():void{[$owner,$mitra,$entity,$rate]=$this->vehicle();$consumer=User::factory()->create();$data=$this->bookingData();$first=app(CreateRentalBooking::class)->execute($entity->rentalVehicle,$rate,$consumer,$data);try{app(CreateRentalBooking::class)->execute($entity->rentalVehicle,$rate,User::factory()->create(),$data);$this->fail('Overlap harus ditolak.');}catch(ValidationException){$this->assertSame('requested',$first->status->value);}$first->update(['status'=>'cancelled']);$entity->rentalVehicle->availability()->create(['service_date'=>now()->addDay()->toDateString(),'status'=>'blocked']);$this->expectException(ValidationException::class);app(CreateRentalBooking::class)->execute($entity->rentalVehicle,$rate,User::factory()->create(),$data);}
public function test_document_approval_and_booking_lifecycle_are_enforced():void{[$owner,$mitra,$entity,$rate]=$this->vehicle();$consumer=User::factory()->create();$asset=MediaAsset::factory()->create(['owner_user_id'=>$consumer->id,'mitra_id'=>null,'visibility'=>'private']);$doc=RenterDocument::create(['user_id'=>$consumer->id,'media_asset_id'=>$asset->id,'document_type'=>'sim_a','document_number'=>'123','status'=>'pending']);$booking=app(CreateRentalBooking::class)->execute($entity->rentalVehicle,$rate,$consumer,$this->bookingData()+['document_ids'=>[$doc->id]]);app(TransitionRentalBooking::class)->execute($booking,'document_review',$owner);try{app(TransitionRentalBooking::class)->execute($booking->fresh(),'approved',$owner);$this->fail('Dokumen pending harus menolak approval.');}catch(ValidationException){$this->assertTrue(true);}$doc->update(['status'=>'approved']);app(TransitionRentalBooking::class)->execute($booking->fresh(),'approved',$owner);app(TransitionRentalBooking::class)->execute($booking->fresh(),'active',$owner);app(TransitionRentalBooking::class)->execute($booking->fresh(),'completed',$owner);$this->assertSame('completed',$booking->fresh()->status->value);$this->assertDatabaseHas('notifications',['user_id'=>$consumer->id]);$this->assertDatabaseHas('audit_logs',['event'=>'rental.booking_completed']);}
public function test_draft_private_and_published_vehicle_visible():void{[$owner,$mitra,$entity]=$this->vehicle();$this->get(route('rental.show',$entity->slug))->assertNotFound();$entity->update(['status'=>'published','published_at'=>now()]);$this->get(route('rental.show',$entity->slug))->assertOk()->assertSee($entity->name);}
private function vehicle():array{$owner=User::factory()->create();$mitra=Mitra::factory()->for($owner,'owner')->create(['status'=>'active','approved_at'=>now()]);$service=ServiceType::where('code','rental')->firstOrFail();$mitra->features()->create(['service_type_id'=>$service->id,'status'=>'enabled']);$entity=CatalogEntity::create(['mitra_id'=>$mitra->id,'service_type_id'=>$service->id,'name'=>'Avanza Tegal','slug'=>'avanza-'.str()->lower(str()->random(5)),'description'=>'Kendaraan terawat untuk perjalanan keluarga.','address'=>'Tegal','status'=>'draft']);$vehicle=$entity->rentalVehicle()->create(['vehicle_type'=>'car','brand'=>'Toyota','model'=>'Avanza','plate_number'=>'G 1234 AB','seats'=>7,'self_drive_available'=>true,'driver_available'=>true,'deposit_amount'=>500000,'status'=>'active']);$offer=CatalogOffer::create(['mitra_id'=>$mitra->id,'catalog_entity_id'=>$entity->id,'offer_type'=>'rental_rate','sku'=>'RV-'.str()->upper(str()->random(6)),'name'=>'Harian','price'=>350000,'status'=>'active']);$rate=RentalRate::create(['rental_vehicle_id'=>$vehicle->id,'catalog_offer_id'=>$offer->id,'drive_mode'=>'self_drive','duration_unit'=>'day','duration_value'=>1]);return[$owner,$mitra,$entity->fresh('rentalVehicle'),$rate];}private function bookingData():array{return['pickup_at'=>now()->addDay()->setTime(8,0),'return_at'=>now()->addDays(2)->setTime(8,0),'pickup_location'=>'Tegal','return_location'=>'Tegal','drive_mode'=>'self_drive'];}}
